import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireGlu Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireGlu/aireglu-v1-123-0.md","filePath":"aireblock-releases/AireGlu/aireglu-v1-123-0.md","lastUpdated":1789463877000}`),a={name:`aireblock-releases/AireGlu/aireglu-v1-123-0.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireglu-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireglu-icon.png"> AireGlu Release Notes</span> <a class="header-anchor" href="#aireglu-release-notes" aria-label="Permalink to “AireGlu Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> v1.123.0<br><strong>Release Date:</strong> 23 September 2026</p></blockquote><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Array Support for Callback Endpoint Output (GLU-2917)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Fixed Repository-Linked MCP Server Resolution (GLU-3275)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="array-support-for-callback-endpoint-output-glu-2917" tabindex="-1">Array Support for Callback Endpoint Output (GLU-2917) <a class="header-anchor" href="#array-support-for-callback-endpoint-output-glu-2917" aria-label="Permalink to “Array Support for Callback Endpoint Output (GLU-2917)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The Callback input type schema now accepts an array, in addition to an object, for originalInput and endpointOutput, since both are valid representations of the same JSON data.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If your callback configuration receives original input or endpoint output as an array rather than a single object, AireGlu will now accept it correctly.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="fixed-repository-linked-mcp-server-resolution-glu-3275" tabindex="-1">Fixed Repository-Linked MCP Server Resolution (GLU-3275) <a class="header-anchor" href="#fixed-repository-linked-mcp-server-resolution-glu-3275" aria-label="Permalink to “Fixed Repository-Linked MCP Server Resolution (GLU-3275)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Repository-linked MCP server configurations were only resolved against the standalone server configuration collection. As a result, a repo-linked server would appear correctly in the server list but return an error when opened directly, and fail with a &quot;server not found&quot; error when a connection or call was attempted against it. Lookups now also fall back to searching the linked repository&#39;s own server configurations, matching the behaviour already used when building the list view.</p></div>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};